function isSearchTree(root: TreeNode | null): boolean {
  const extreme = (n: TreeNode | null, pick: (a: number, b: number) => number, start: number): number =>
    n ? pick(n.val, pick(extreme(n.left, pick, start), extreme(n.right, pick, start))) : start;
  const ok = (n: TreeNode | null): boolean => {
    if (!n) return true;
    if (extreme(n.left, Math.max, -Infinity) >= n.val) return false;
    if (extreme(n.right, Math.min, Infinity) <= n.val) return false;
    return ok(n.left) && ok(n.right);
  };
  return ok(root);
}

