    def isSearchTree(self, root: Optional[TreeNode]) -> bool:
        def biggest(n):
            return max(n.val, biggest(n.left), biggest(n.right)) if n else -math.inf

        def smallest(n):
            return min(n.val, smallest(n.left), smallest(n.right)) if n else math.inf

        def ok(n):
            if not n:
                return True
            if biggest(n.left) >= n.val or smallest(n.right) <= n.val:
                return False
            return ok(n.left) and ok(n.right)

        return ok(root)

