function isSearchTree(root: TreeNode | null): boolean {
  // null bound = no bound, so the 32-bit extremes are still allowed values
  const check = (n: TreeNode | null, low: number | null, high: number | null): boolean => {
    if (!n) return true;
    if (low !== null && n.val <= low) return false;
    if (high !== null && n.val >= high) return false;
    return check(n.left, low, n.val) && check(n.right, n.val, high);
  };
  return check(root, null, null);
}

