function isSearchTree(root: TreeNode | null): boolean {
  const stack: TreeNode[] = [];
  let prev: number | null = null, n = root;
  while (n || stack.length) {
    while (n) { stack.push(n); n = n.left; }
    n = stack.pop()!;
    if (prev !== null && n.val <= prev) return false;
    prev = n.val;
    n = n.right;
  }
  return true;
}

